const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const sourceFiles = ['README.md','draft-summary.md','study/protocol.md','evidence/capture-notes.md','evidence/pairs.csv','evidence/reference.csv','evidence/guide.csv','guides/reference-card.txt','guides/reorganized-guide.txt','tools/check-evidence.cjs'];
const sources = Object.fromEntries(sourceFiles.map(file => [file, crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex')]));
function csv(file) {
  const [header, ...lines] = fs.readFileSync(file, 'utf8').trimEnd().split(/\\r?\\n/);
  const keys = header.split(',');
  return lines.map(line => {
    const cells = line.split(',');
    assert.equal(cells.length, keys.length);
    return Object.fromEntries(keys.map((key, index) => [key, cells[index]]));
  });
}
function byId(rows) {
  const map = new Map(rows.map(row => [row.pair_id, row]));
  assert.equal(map.size, rows.length);
  return map;
}
const pairs = csv('evidence/pairs.csv');
const reference = byId(csv('evidence/reference.csv'));
const guide = byId(csv('evidence/guide.csv'));
const pairIds = pairs.map(row => row.pair_id).sort();
assert.equal(new Set(pairIds).size, pairs.length);
assert.deepEqual([...reference.keys()].sort(), pairIds);
assert.deepEqual([...guide.keys()].sort(), pairIds);
function seconds(cell) {
  if (cell === '') return null;
  const value = Number(cell);
  assert(Number.isFinite(value) && value > 0);
  return value;
}
const rows = pairs.map(pair => {
  const r = reference.get(pair.pair_id);
  const g = guide.get(pair.pair_id);
  for (const row of [r, g]) for (const field of ['correct', 'assisted']) assert(['true', 'false'].includes(row[field]));
  const refSeconds = seconds(r.seconds), guideSeconds = seconds(g.seconds);
  return {...pair, reference_seconds: refSeconds, guide_seconds: guideSeconds, saved_seconds: refSeconds === null || guideSeconds === null ? null : refSeconds - guideSeconds, reference_correct: r.correct === 'true', guide_correct: g.correct === 'true', reference_assisted: r.assisted === 'true', guide_assisted: g.assisted === 'true'};
});
const eligible = rows.filter(row => row.saved_seconds "'!== null);
const sum = (group, key) => group.reduce((total, row) => total + row[key], 0);
const metrics = {
  eligible_time_pairs: eligible.length,
  reference_seconds: sum(eligible, '"'reference_seconds'),
  guide_seconds: sum(eligible, 'guide_seconds'),
  time_saved_seconds: sum(eligible, 'saved_seconds'),
  faster_pairs: eligible.filter(row => row.saved_seconds > 0).length,
  slower_pairs: eligible.filter(row => row.saved_seconds < 0).length,
  tied_pairs: eligible.filter(row => row.saved_seconds === 0).length,
  accuracy_pairs: rows.length,
  reference_correct: rows.filter(row => row.reference_correct).length,
  guide_correct: rows.filter(row => row.guide_correct).length
};
assert.equal(metrics.time_saved_seconds, metrics.reference_seconds - metrics.guide_seconds);
assert.equal(metrics.eligible_time_pairs, metrics.faster_pairs + metrics.slower_pairs + metrics.tied_pairs);
const subgroups = {};
for (const order of ['reference', 'guide']) {
  const group = eligible.filter(row => row.first_format === order);
  subgroups[order + '_first'] = {pairs: group.map(row => row.pair_id), reference_seconds: sum(group, 'reference_seconds'), guide_seconds: sum(group, 'guide_seconds'), saved_seconds: sum(group, 'saved_seconds')};
}
const unassisted = eligible.filter(row => "'!row.reference_assisted && !row.guide_assisted);
const result = {metrics, percent_saving: metrics.time_saved_seconds / metrics.reference_seconds * 100, rows, order_subgroups: subgroups, unassisted_sensitivity: {pairs: unassisted.map(row => row.pair_id), reference_seconds: sum(unassisted, '"'reference_seconds'), guide_seconds: sum(unassisted, 'guide_seconds'), saved_seconds: sum(unassisted, 'saved_seconds')}, source_sha256: sources};
fs.mkdirSync('audit', {recursive: true});
fs.writeFileSync('audit/metrics.json', JSON.stringify(metrics, null, 2) + '\\n');
fs.writeFileSync('audit/.verification.json', JSON.stringify(result, null, 2) + '\\n');
process.stdout.write(JSON.stringify(result, null, 2) + '\\n');
