const fs = require('node:fs');
const crypto = require('node:crypto');
const assert = require('node:assert/strict');
const verification = JSON.parse(fs.readFileSync('audit/.verification.json', 'utf8'));
for (const [file, expected] of Object.entries(verification.source_sha256)) {
  assert.equal(crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'), expected, 'Source changed: ' + file);
}
const metrics = JSON.parse(fs.readFileSync('audit/metrics.json', 'utf8'));
