assert(Object.values(metrics).every(value => Number.isInteger(value) && value >= 0));
assert.equal(metrics.time_saved_seconds, metrics.reference_seconds - metrics.guide_seconds);
assert.equal(metrics.faster_pairs + metrics.slower_pairs + metrics.tied_pairs, metrics.eligible_time_pairs);
assert.equal(verification.rows.filter(row => row.saved_seconds === null).map(row => row.pair_id).join(','), 'P7');
assert(verification.rows.find(row => row.pair_id === 'P7').guide_correct);
assert(verification.rows.find(row => row.pair_id === 'P7').guide_assisted);
