assert.equal(verification.rows.find(row => row.pair_id === 'P5').guide_correct, false);
const report = fs.readFileSync('audit/findings.md', 'utf8');
const targets = [...report.matchAll(/\\]\\((["'^)]+)'"\\)/g)].map(match => match[1]);
const path = require('node:path');
for (const target of targets) assert(fs.existsSync(path.resolve('audit', target)), 'Missing report link: ' + target);
process.stdout.write(JSON.stringify({source_hashes_checked: Object.keys(verification.source_sha256).length, all_sources_unchanged: true, json_validation: 'PASS', linked_local_files_checked: targets.length}, null, 2) + '\\n');
