"<PROGRAM_FILES>\\POWERS~1\\7\\pwsh.exe" -Command '$ErrorActionPreference = '"'Stop'
"'$pairs = @(Import-Csv -LiteralPath evidence/pairs.csv)
$referenceRows = @(Import-Csv -LiteralPath evidence/reference.csv)
$guideRows = @(Import-Csv -LiteralPath evidence/guide.csv)
$referenceById = @{}
$guideById = @{}
foreach ($row in $referenceRows) { $referenceById[$row.pair_id] = $row }
foreach ($row in $guideRows) { $guideById[$row.pair_id] = $row }
$joined = @(foreach ($pair in $pairs) {
    $ref = $referenceById[$pair.pair_id]
    $guide = $guideById[$pair.pair_id]
    $eligible = -not [string]::IsNullOrWhiteSpace($ref.seconds) -and -not [string]::IsNullOrWhiteSpace($guide.seconds)
    if ($eligible) { $eligible = [double]$ref.seconds -gt 0 -and [double]$guide.seconds -gt 0 }
    [pscustomobject]@{ pair_id = $pair.pair_id; reference = $ref; guide = $guide; eligible = $eligible }
})
$timed = @($joined | Where-Object eligible)
$refTotal = ($timed | ForEach-Object { [int]$_.reference.seconds } | Measure-Object -Sum).Sum
$guideTotal = ($timed | ForEach-Object { [int]$_.guide.seconds } | Measure-Object -Sum).Sum
$expected = [ordered]@{
    eligible_time_pairs = $timed.Count
    reference_seconds = $refTotal
    guide_seconds = $guideTotal
    time_saved_seconds = $refTotal - $guideTotal
    faster_pairs = @($timed | Where-Object { [int]$_.guide.seconds -lt [int]$_.reference.seconds }).Count
    slower_pairs = @($timed | Where-Object { [int]$_.guide.seconds -gt [int]$_.reference.seconds }).Count
    tied_pairs = @($timed | Where-Object { [int]$_.guide.seconds -eq [int]$_.reference.seconds }).Count
    accuracy_pairs = @($joined | Where-Object { $_.reference.correct -in @('"'true', 'false') -and "'$_.guide.correct -in @('"'true', 'false') }).Count
    reference_correct = @("'$referenceRows | Where-Object correct -EQ '"'true').Count
    guide_correct = @("'$guideRows | Where-Object correct -EQ '"'true').Count
}
"'$actual = Get-Content -Raw -LiteralPath audit/metrics.json | ConvertFrom-Json
$keys = @($actual.PSObject.Properties.Name)
if (@(Compare-Object ($expected.Keys | Sort-Object) ($keys | Sort-Object)).Count -ne 0) { throw '"'JSON field set mismatch' }
foreach ("'$key in $expected.Keys) {
    $value = $actual.$key
    if ($value -isnot [ValueType] -or $value -is [bool] -or $value -ne $expected[$key]) { throw "Numeric metric mismatch: $key" }
}
if (@($pairs.volunteer_id | Sort-Object -Unique).Count -ne 4) { throw '"'Volunteer count mismatch' }
foreach ("'$group in ($pairs | Group-Object volunteer_id)) {
    if ($group.Count -ne 2 -or @($group.Group | Where-Object first_format -EQ reference).Count -ne 1 -or @($group.Group | Where-Object first_format -EQ guide).Count -ne 1) { throw '"'Order balance mismatch' }
}
[pscustomobject]@{ verified_fields = "'$keys.Count; metrics = $expected; percent_saving = ($refTotal - $guideTotal) / $refTotal * 100; reference_assisted = @($referenceRows | Where-Object assisted -EQ true).Count; guide_assisted = @($guideRows | Where-Object assisted -EQ true).Count; status = '"'PASS' } | ConvertTo-Json -Depth 4"
